	</main>
	<script>
		(function () {
			var canvas = document.querySelector('.ambient canvas');
			var context = canvas && canvas.getContext('2d');
			if (!context) return;

			var points = [];
			var width = 0;
			var height = 0;
			var pixelRatio = Math.min(window.devicePixelRatio || 1, 2);
			var pointer = { x: -1000, y: -1000, active: false };
			var reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
			var frame = 0;

			function resize() {
				width = window.innerWidth;
				height = window.innerHeight;
				pixelRatio = Math.min(window.devicePixelRatio || 1, 2);
				canvas.width = Math.round(width * pixelRatio);
				canvas.height = Math.round(height * pixelRatio);
				context.setTransform(pixelRatio, 0, 0, pixelRatio, 0, 0);

				var count = Math.max(48, Math.min(110, Math.round((width * height) / 11500)));
				points = Array.from({ length: count }, function () {
					return {
						x: Math.random() * width,
						y: Math.random() * height,
						vx: (Math.random() - .5) * .34,
						vy: (Math.random() - .5) * .34,
						radius: 1.4 + Math.random() * 1.8
					};
				});
				draw();
			}

			function draw() {
				context.clearRect(0, 0, width, height);
				if (pointer.active) {
					var glow = context.createRadialGradient(pointer.x, pointer.y, 0, pointer.x, pointer.y, 210);
					glow.addColorStop(0, 'rgba(76,84,96,.18)');
					glow.addColorStop(.42, 'rgba(76,84,96,.09)');
					glow.addColorStop(1, 'rgba(76,84,96,0)');
					context.fillStyle = glow;
					context.fillRect(pointer.x - 210, pointer.y - 210, 420, 420);

					context.beginPath();
					context.arc(pointer.x, pointer.y, 48, 0, Math.PI * 2);
					context.strokeStyle = 'rgba(55, 63, 75, .48)';
					context.lineWidth = 1.5;
					context.stroke();
					context.beginPath();
					context.arc(pointer.x, pointer.y, 57, 0, Math.PI * 2);
					context.strokeStyle = 'rgba(55, 63, 75, .2)';
					context.lineWidth = 1;
					context.stroke();
				}

				for (var i = 0; i < points.length; i++) {
					var point = points[i];
					if (!reducedMotion) {
						if (pointer.active) {
							var influenceX = point.x - pointer.x;
							var influenceY = point.y - pointer.y;
							var influenceDistance = Math.sqrt(influenceX * influenceX + influenceY * influenceY);
							if (influenceDistance < 175 && influenceDistance > 0) {
								var push = (175 - influenceDistance) / 175 * .52;
								point.vx += influenceX / influenceDistance * push;
								point.vy += influenceY / influenceDistance * push;
							}
						}
						point.vx *= .985;
						point.vy *= .985;
						var speed = Math.sqrt(point.vx * point.vx + point.vy * point.vy);
						if (speed > 2.8) {
							point.vx = point.vx / speed * 2.8;
							point.vy = point.vy / speed * 2.8;
						}
						point.x += point.vx;
						point.y += point.vy;
						if (point.x < -8) point.x = width + 8;
						if (point.x > width + 8) point.x = -8;
						if (point.y < -8) point.y = height + 8;
						if (point.y > height + 8) point.y = -8;
					}

					var dx = point.x - pointer.x;
					var dy = point.y - pointer.y;
					var distance = Math.sqrt(dx * dx + dy * dy);

					for (var j = i + 1; j < points.length; j++) {
						var next = points[j];
						var lineX = point.x - next.x;
						var lineY = point.y - next.y;
						var lineDistance = Math.sqrt(lineX * lineX + lineY * lineY);
						var nearPointer = pointer.active && (distance < 210 || Math.sqrt((next.x - pointer.x) * (next.x - pointer.x) + (next.y - pointer.y) * (next.y - pointer.y)) < 210);
						if (lineDistance < 150 && (!pointer.active || nearPointer || lineDistance < 100)) {
							context.beginPath();
							context.moveTo(point.x, point.y);
							context.lineTo(next.x, next.y);
							context.strokeStyle = 'rgba(55, 63, 75, ' + ((1 - lineDistance / 150) * (nearPointer ? .58 : .3)) + ')';
							context.lineWidth = nearPointer ? 1.2 : 1;
							context.stroke();
						}
					}

					context.beginPath();
					context.arc(point.x, point.y, point.radius + (pointer.active && distance < 130 ? 1 : 0), 0, Math.PI * 2);
					context.fillStyle = pointer.active && distance < 175 ? 'rgba(42, 49, 60, .9)' : 'rgba(65, 73, 84, .68)';
					context.fill();
				}

				if (!reducedMotion) frame = window.requestAnimationFrame(draw);
			}

			window.addEventListener('resize', resize, { passive: true });
			window.addEventListener('pointermove', function (event) {
				pointer.x = event.clientX;
				pointer.y = event.clientY;
				pointer.active = true;
				document.documentElement.style.setProperty('--pointer-x', pointer.x + 'px');
				document.documentElement.style.setProperty('--pointer-y', pointer.y + 'px');
				if (reducedMotion && !frame) frame = window.requestAnimationFrame(function () { frame = 0; draw(); });
			}, { passive: true });
			window.addEventListener('pointerleave', function () {
				pointer.active = false;
				document.documentElement.style.setProperty('--pointer-x', '50%');
				document.documentElement.style.setProperty('--pointer-y', '45%');
				if (reducedMotion && !frame) frame = window.requestAnimationFrame(function () { frame = 0; draw(); });
			}, { passive: true });

			resize();
		}());
	</script>
</body>
</html>
